import {AgenticAutofixErrorBanner} from '@github-ui/code-scanning-shared/components/AgenticAutofixErrorBanner'
import {useAgenticAutofixJobPoll} from '@github-ui/code-scanning-shared/hooks/use-agentic-autofix-job-poll'
import {AgenticAutofixError} from '@github-ui/code-scanning-shared/types/agentic-autofix-error'
import {displayFlashMessage} from '@github-ui/code-scanning-shared/utils/display-flash-message'
import {AgentIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import styles from './CodeScanningAssignToCopilotButton.module.css'
import {useCallback, useEffect, useState} from 'react'
import {createPortal} from 'react-dom'
import {useAssignToCopilotMutation} from '@github-ui/code-scanning-shared/hooks/use-assign-to-copilot-mutation'

export type CodeScanningAssignToCopilotButtonProps = {
  path: string
  alertNumbers: number[]
  alertNumbersElementId?: string
  repositoryOwner: string
  repositoryName: string
  errorContainerId?: string
}

export function CodeScanningAssignToCopilotButton({
  path,
  alertNumbers: initialAlertNumbers,
  alertNumbersElementId,
  repositoryOwner,
  repositoryName,
  errorContainerId,
}: CodeScanningAssignToCopilotButtonProps) {
  const [alertNumbers, setAlertNumbers] = useState<number[]>(initialAlertNumbers)
  const [errorState, setErrorState] = useState<{error: AgenticAutofixError; container: HTMLElement} | null>(null)
  const [agenticAutofixJobId, setAgenticAutofixJobId] = useState<string | null>(null)
  const {mutate: mutateAssignToCopilot, isPending} = useAssignToCopilotMutation(path)

  const handleAgenticAutofixJobError = useCallback((message: string) => {
    displayFlashMessage('error', `Copilot failed to create a pull request. ${message}.`)
    setAgenticAutofixJobId(null)
  }, [])

  useAgenticAutofixJobPoll(repositoryOwner, repositoryName, agenticAutofixJobId, handleAgenticAutofixJobError)

  useEffect(() => {
    if (!alertNumbersElementId) {
      return
    }

    const alertNumbersElement = document.getElementById(alertNumbersElementId)
    if (!alertNumbersElement) {
      return
    }

    const listener = () => {
      setAlertNumbers(JSON.parse(alertNumbersElement.textContent ?? '[]'))
    }

    alertNumbersElement.addEventListener('change', listener)
    return () => {
      alertNumbersElement.removeEventListener('change', listener)
    }
  }, [alertNumbersElementId])

  const handleAssignToCopilotClick = useCallback(() => {
    setErrorState(null)
    mutateAssignToCopilot(
      {
        alertNumbers,
      },
      {
        onSuccess: data => {
          displayFlashMessage(
            'success',
            'Successfully assigned alerts to Copilot. Copilot will open pull requests as fixes are generated.',
          )
          if (data.agenticAutofixJobId) {
            setAgenticAutofixJobId(data.agenticAutofixJobId)
          }
        },
        onError: (mutationError: Error) => {
          if (mutationError instanceof AgenticAutofixError) {
            const container = errorContainerId ? document.getElementById(errorContainerId) : null
            if (container) {
              setErrorState({error: mutationError, container})
            } else {
              displayFlashMessage('error', mutationError.message)
            }
          } else {
            displayFlashMessage('error', 'Something went wrong, please try again.')
          }
        },
      },
    )
  }, [alertNumbers, mutateAssignToCopilot, errorContainerId])

  const handleRetry = useCallback(() => {
    setErrorState(null)
    handleAssignToCopilotClick()
  }, [handleAssignToCopilotClick])

  const handleDismiss = useCallback(() => {
    setErrorState(null)
  }, [])

  return (
    <>
      {errorState &&
        createPortal(
          <div className={styles.errorBannerWrapper}>
            <AgenticAutofixErrorBanner
              error={errorState.error}
              repository={{owner: repositoryOwner, name: repositoryName}}
              onRetry={handleRetry}
              onDismiss={handleDismiss}
            />
          </div>,
          errorState.container,
        )}
      <Button loading={isPending} onClick={handleAssignToCopilotClick} leadingVisual={AgentIcon}>
        Assign to Copilot
      </Button>
    </>
  )
}
